13	private final class WeakSessionVerificationControllerProxy: SessionVerificationControllerDelegate {
14	    private weak var proxy: SessionVerificationControllerProxy?
15	    
16	    init(proxy: SessionVerificationControllerProxy) {
17	        self.proxy = proxy
18	    }
19	    
20	    // MARK: - SessionVerificationControllerDelegate
21	    
22	    func didReceiveVerificationRequest(details: MatrixRustSDK.SessionVerificationRequestDetails) {
23	        proxy?.didReceiveVerificationRequest(details: details)
24	    }
25	    
26	    func didReceiveVerificationData(data: MatrixRustSDK.SessionVerificationData) {
27	        switch data {
28	        // We can handle only emojis for now
29	        case .emojis(let emojis, _):
30	            proxy?.didReceiveData(emojis)
31	        default:
32	            break
33	        }
34	    }
35	    
36	    func didAcceptVerificationRequest() {
37	        proxy?.didAcceptVerificationRequest()
38	    }
39	    
40	    func didStartSasVerification() {
41	        proxy?.didStartSasVerification()
42	    }
43	    
44	    func didFail() {
45	        proxy?.didFail()
46	    }
47	    
48	    func didCancel() {
49	        proxy?.didCancel()
50	    }
51	    
52	    func didFinish() {
53	        proxy?.didFinish()
54	    }
55	}
