40	final class SessionVerificationScreenCoordinator: CoordinatorProtocol {
41	    private var viewModel: SessionVerificationScreenViewModelProtocol
42	    
43	    private let actionsSubject: PassthroughSubject<SessionVerificationScreenCoordinatorAction, Never> = .init()
44	    private var cancellables = Set<AnyCancellable>()
45	    
46	    var actions: AnyPublisher<SessionVerificationScreenCoordinatorAction, Never> {
47	        actionsSubject.eraseToAnyPublisher()
48	    }
49	    
50	    init(parameters: SessionVerificationScreenCoordinatorParameters) {
51	        viewModel = SessionVerificationScreenViewModel(sessionVerificationControllerProxy: parameters.sessionVerificationControllerProxy,
52	                                                       flow: parameters.flow,
53	                                                       appSettings: parameters.appSettings,
54	                                                       mediaProvider: parameters.mediaProvider)
55	    }
56	    
57	    // MARK: - Public
58	    
59	    func start() {
60	        viewModel.actions
61	            .sink { [weak self] action in
62	                guard let self else { return }
63	                
64	                switch action {
65	                case .finished:
66	                    actionsSubject.send(.done)
67	                }
68	            }
69	            .store(in: &cancellables)
70	    }
71	    
72	    func stop() {
73	        viewModel.stop()
74	    }
75	    
76	    func toPresentable() -> AnyView {
77	        AnyView(SessionVerificationScreen(context: viewModel.context))
78	    }
79	}
